16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.temporal.ChronoUnit;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "address_line1")
44	    private String addressLine1;
45	
46	    @Column(name = "address_line2")
47	    private String addressLine2;
48	
49	    @Column(name = "city")
50	    @NotEmpty
51	    private String city;
52	
53	    @Column(name = "postcode")
54	    private String postcode;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ then 8 to 15 digits)")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "registration_date")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "birth_date")
68	    private LocalDate birthDate;
69	
70	    @Column(name = "customer_code")
71	    private String customerCode;
72	
73	    @Column(name = "membership_number")
74	    private String membershipNumber;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Transient
83	    private Integer householdSize;
84	
85	    @Transient
86	    private Boolean bulkSignupWarning;
87	
88	    @Transient
89	    private Boolean possibleDuplicate;
90	
91	    @Transient
92	    private Integer possibleDuplicateOf;
93	
94	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
95	    private Set<Pet> pets;
96	
97	    public String getAddress() {
98	        return this.address;
99	    }
100	
101	    public void setAddress(String address) {
102	        this.address = address;
103	    }
104	
105	    /**
106	     * The first line of the structured postal address (street number and name), or {@code null} when
107	     * the owner was supplied with only the flat {@link #getAddress() address}. The preferred street
108	     * address when present; {@link #getAddress() address} holds the composed form.
109	     */
110	    public String getAddressLine1() {
111	        return this.addressLine1;
112	    }
113	
114	    public void setAddressLine1(String addressLine1) {
115	        this.addressLine1 = addressLine1;
116	    }
117	
118	    /**
119	     * The optional second line of the structured postal address (unit, suite, etc.), or {@code null}
120	     * when none was supplied. When present it is appended to the composed {@link #getAddress() address}.
121	     */
122	    public String getAddressLine2() {
123	        return this.addressLine2;
124	    }
125	
126	    public void setAddressLine2(String addressLine2) {
127	        this.addressLine2 = addressLine2;
128	    }
129	
130	    public String getCity() {
131	        return this.city;
132	    }
133	
134	    public void setCity(String city) {
135	        this.city = city;
136	    }
137	
138	    public String getPostcode() {
139	        return this.postcode;
140	    }
141	
142	    public void setPostcode(String postcode) {
143	        this.postcode = postcode;
144	    }
145	
146	    public String getTelephone() {
147	        return this.telephone;
148	    }
149	
150	    public void setTelephone(String telephone) {
151	        this.telephone = telephone;
152	    }
153	
154	    /**
155	     * The stored {@link #getTelephone() telephone} formatted for humans by {@link TelephoneFormatter}:
156	     * the country code, a space, then the national digits grouped in threes (e.g. {@code +61412345678}
157	     * -> {@code +61 412 345 678}). The raw {@link #getTelephone() telephone} stays in E.164 form.
158	     */
159	    public String getTelephoneDisplay() {
160	        return TelephoneFormatter.toDisplay(this.telephone);
161	    }
162	
163	    public String getEmail() {
164	        return this.email;
165	    }
166	
167	    public void setEmail(String email) {
168	        this.email = email;
169	    }
170	
171	    public LocalDate getRegistrationDate() {
172	        return this.registrationDate;
173	    }
174	
175	    public void setRegistrationDate(LocalDate registrationDate) {
176	        this.registrationDate = registrationDate;
177	    }
178	
179	    public LocalDate getBirthDate() {
180	        return this.birthDate;
181	    }
182	
183	    public void setBirthDate(LocalDate birthDate) {
184	        this.birthDate = birthDate;
185	    }
186	
187	    /**
188	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
189	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
190	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
191	     * (so the field is absent from the response) or the registration date is unknown.
192	     */
193	    public String getAgeBand() {
194	        if (this.birthDate == null || this.registrationDate == null) {
195	            return null;
196	        }
197	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
198	        if (age < 18) {
199	            return "MINOR";
200	        }
201	        if (age < 65) {
202	            return "ADULT";
203	        }
204	        return "SENIOR";
205	    }
206	
207	    public String getCustomerCode() {
208	        return this.customerCode;
209	    }
210	
211	    public void setCustomerCode(String customerCode) {
212	        this.customerCode = customerCode;
213	    }
214	
215	    public String getMembershipNumber() {
216	        return this.membershipNumber;
217	    }
218	
219	    public void setMembershipNumber(String membershipNumber) {
220	        this.membershipNumber = membershipNumber;
221	    }
222	
223	    public String getHouseholdId() {
224	        return this.householdId;
225	    }
226	
227	    public void setHouseholdId(String householdId) {
228	        this.householdId = householdId;
229	    }
230	
231	    public Integer getNamesakeCount() {
232	        return this.namesakeCount;
233	    }
234	
235	    public void setNamesakeCount(Integer namesakeCount) {
236	        this.namesakeCount = namesakeCount;
237	    }
238	
239	    /**
240	     * Sets the number of owners that belong to this owner's household (same last name and postcode; see
241	     * {@link org.springframework.samples.petclinic.rest.function.owner.Household}), including this owner.
242	     * Computed per request and used only by {@link #getMembershipPoints()} — a household of three or more
243	     * contributes points. Not persisted and not serialized into the response (no getter is exposed); the
244	     * count is recomputed on each read because household membership changes as owners come and go.
245	     */
246	    public void setHouseholdSize(Integer householdSize) {
247	        this.householdSize = householdSize;
248	    }
249	
250	    /**
251	     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
252	     * have already been created for this owner's registration day. Computed per request, not persisted.
253	     */
254	    public Boolean getBulkSignupWarning() {
255	        return this.bulkSignupWarning;
256	    }
257	
258	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
259	        this.bulkSignupWarning = bulkSignupWarning;
260	    }
261	
262	    /**
263	     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
264	     * other owner shares this owner's last name (case-insensitively) and postcode but has a different
265	     * telephone — a near match. Always false for an owner admitted as a declared household member (via
266	     * {@code sharesHousehold}), which is not a suspected duplicate.
267	     * Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched owner.
268	     */
269	    public Boolean getPossibleDuplicate() {
270	        return this.possibleDuplicate;
271	    }
272	
273	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
274	        this.possibleDuplicate = possibleDuplicate;
275	    }
276	
277	    /**
278	     * The id of the existing owner this owner possibly duplicates (same last name and postcode, different
279	     * telephone), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is false. When
280	     * several owners match, this is the earliest (lowest id). Computed per request, not persisted.
281	     */
282	    public Integer getPossibleDuplicateOf() {
283	        return this.possibleDuplicateOf;
284	    }
285	
286	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
287	        this.possibleDuplicateOf = possibleDuplicateOf;
288	    }
289	
290	    /**
291	     * The owner's membership points: start at 0; add 2 when an email is present; add 1 when
292	     * {@code namesakeCount} is 0; add 2 for a household of 3 or more members (see
293	     * {@link #setHouseholdSize(Integer)}); add 3 for tenure of more than 365 days (measured from
294	     * {@code registrationDate} to today). A newly created owner has zero tenure, so a fresh owner scores
295	     * at most 5 points (2 + 1 + 2).
296	     */
297	    public int getMembershipPoints() {
298	        int points = 0;
299	        boolean hasEmail = this.email != null && !this.email.isBlank();
300	        if (hasEmail) {
301	            points += 2;
302	        }
303	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
304	        if (unique) {
305	            points += 1;
306	        }
307	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
308	        if (largeHousehold) {
309	            points += 2;
310	        }
311	        boolean tenured = this.registrationDate != null
312	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
313	        if (tenured) {
314	            points += 3;
315	        }
316	        return points;
317	    }
318	
319	    /**
320	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
321	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
322	     */
323	    public int getMembershipLevel() {
324	        int points = getMembershipPoints();
325	        if (points <= 1) {
326	            return 1;
327	        }
328	        if (points <= 3) {
329	            return 2;
330	        }
331	        if (points <= 5) {
332	            return 3;
333	        }
334	        return 4;
335	    }
336	
337	    /**
338	     * Fixed city-to-region table mapping each known city to its canonical region string.
339	     */
340	    private static final Map<String, String> CITY_REGION = Map.of(
341	        "Sydney", "NSW",
342	        "Melbourne", "VIC",
343	        "Brisbane", "QLD");
344	
345	    /**
346	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
347	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
348	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
349	     */
350	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
351	        "NSW", new int[] {2000, 2099},
352	        "VIC", new int[] {3000, 3099},
353	        "QLD", new int[] {4000, 4099});
354	
355	    /**
356	     * Fixed region-to-timezone table mapping each known region to its IANA timezone name
357	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). The single
358	     * source of truth for the timezone derivation read by {@link #getTimezone()}.
359	     */
360	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
361	        "NSW", "Australia/Sydney",
362	        "VIC", "Australia/Melbourne",
363	        "QLD", "Australia/Brisbane");
364	
365	    /**
366	     * The canonical region for {@code city} derived from the fixed city-to-region table
367	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
368	     * city is not in the table. The single source of truth for the create-time postcode range check in
369	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
370	     */
371	    public static String regionOf(String city) {
372	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
373	    }
374	
375	    /**
376	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
377	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
378	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
379	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
380	     * postcode range check.
381	     */
382	    public static int[] postcodeRangeOf(String region) {
383	        return REGION_POSTCODES.get(region);
384	    }
385	
386	    /**
387	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
388	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
389	     * range.
390	     */
391	    public static String regionOfPostcode(String postcode) {
392	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
393	            return null;
394	        }
395	        int value = Integer.parseInt(postcode);
396	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
397	            int[] range = entry.getValue();
398	            if (value >= range[0] && value <= range[1]) {
399	                return entry.getKey();
400	            }
401	        }
402	        return null;
403	    }
404	
405	    /**
406	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
407	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
408	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
409	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
410	     * customer code is assigned.
411	     */
412	    public String getLocality() {
413	        if (this.customerCode == null) {
414	            return "UNKNOWN";
415	        }
416	        int dash = this.customerCode.indexOf('-');
417	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
418	    }
419	
420	    /**
421	     * The owner's IANA timezone, derived from the {@link #getLocality() locality}/region via the fixed
422	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
423	     * QLD -> Australia/Brisbane), or {@code null} (so the field is absent from the response) when the
424	     * locality maps to no known region.
425	     */
426	    public String getTimezone() {
427	        return REGION_TIMEZONE.get(getLocality());
428	    }
429	
430	    /**
431	     * The single Luhn check digit (0-9) computed over the digits contained in the
432	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
433	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
434	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
435	     */
436	    public int getCheckDigit() {
437	        String code = this.customerCode;
438	        if (code == null) {
439	            return 0;
440	        }
441	        int sum = 0;
442	        boolean dbl = true;
443	        for (int i = code.length() - 1; i >= 0; i--) {
444	            char c = code.charAt(i);
445	            if (c < '0' || c > '9') {
446	                continue;
447	            }
448	            int d = c - '0';
449	            if (dbl) {
450	                d *= 2;
451	                if (d > 9) {
452	                    d -= 9;
453	                }
454	            }
455	            sum += d;
456	            dbl = !dbl;
457	        }
458	        return (10 - (sum % 10)) % 10;
459	    }
460	
461	    /**
462	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
463	     * {@code "PHONE"}.
464	     */
465	    public String getContactPreference() {
466	        boolean hasEmail = this.email != null && !this.email.isBlank();
467	        return hasEmail ? "EMAIL" : "PHONE";
468	    }
469	
470	    /**
471	     * The single canonical format of an owner's derived identity key:
472	     * {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The telephone and
473	     * household id are used as given (they are expected to already be canonical: E.164 and an assigned
474	     * household id); the email is lower-cased here and a null/blank email, telephone or household id
475	     * contributes an empty component. This is the only place the {@code "|"}-join lives; the stored-owner
476	     * {@link #getIdentityKey()} routes through here so the format cannot drift. The key is a descriptive,
477	     * returned field; create-time duplicate detection itself is keyed on the household alone (see
478	     * {@code CheckHouseholdUnique}).
479	     */
480	    public static String identityKey(String telephone, String email, String householdId) {
481	        String tel = (telephone == null) ? "" : telephone;
482	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
483	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
484	        return tel + "|" + mail + "|" + household;
485	    }
486	
487	    /**
488	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
489	     * household id via {@link #identityKey(String, String, String)}. A descriptive, returned value;
490	     * create-time duplicate detection is keyed on the household (see {@code CheckHouseholdUnique}).
491	     */
492	    public String getIdentityKey() {
493	        return identityKey(this.telephone, this.email, this.householdId);
494	    }
495	
496	    protected Set<Pet> getPetsInternal() {
497	        if (this.pets == null) {
498	            this.pets = new HashSet<>();
499	        }
500	        return this.pets;
501	    }
502	
503	    protected void setPetsInternal(Set<Pet> pets) {
504	        this.pets = pets;
505	    }
506	
507	    public List<Pet> getPets() {
508	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
509	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
510	        return Collections.unmodifiableList(sortedPets);
511	    }
512	
513	    public void setPets(List<Pet> pets) {
514	        this.pets = new HashSet<>(pets);
515	    }
516	
517	    public void addPet(Pet pet) {
518	        getPetsInternal().add(pet);
519	        pet.setOwner(this);
520	    }
521	
522	    /**
523	     * Return the Pet with the given name, or null if none found for this Owner.
524	     *
525	     * @param name to test
526	     * @return true if pet name is already in use
527	     */
528	    public Pet getPet(String name) {
529	        return getPet(name, false);
530	    }
531	
532	    /**
533	     * Return the Pet with the given name, or null if none found for this Owner.
534	     *
535	     * @param name to test
536	     * @return true if pet name is already in use
537	     */
538	    public Pet getPet(String name, boolean ignoreNew) {
539	        name = name.toLowerCase();
540	        for (Pet pet : getPetsInternal()) {
541	            if (!ignoreNew || !pet.isNew()) {
542	                String compName = pet.getName();
543	                compName = compName.toLowerCase();
544	                if (compName.equals(name)) {
545	                    return pet;
546	                }
547	            }
548	        }
549	        return null;
550	    }
551	
552	    public Pet getPet(Integer petId) {
553	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
554	    }
555	
556	    @Override
557	    public String toString() {
558	        return new ToStringCreator(this)
559	
560	            .append("id", this.getId())
561	            .append("new", this.isNew())
562	            .append("lastName", this.getLastName())
563	            .append("firstName", this.getFirstName())
564	            .append("address", this.address)
565	            .append("city", this.city)
566	            .append("telephone", this.telephone)
567	            .toString();
568	    }
569	}
